#!/bin/bash
# Range gateway: brings up WireGuard, enables routing, and installs the NAT/firewall rules that make
# the sim behave like a real competition network.
set -eu

echo "[gateway] enabling IP forwarding"
sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1 || true

echo "[gateway] bringing up WireGuard (wg0)"
# wg0.conf is mounted at /etc/wireguard/wg0.conf (generated by scripts/gen-wg.sh)
wg-quick up wg0

# --- NAT: masquerade everything heading for a VULNBOX network -----------------------------------
# Effect: a vulnbox sees checker traffic and attacker traffic as coming from the gateway's own
# team-side address (10.60.N.254), i.e. from inside its own subnet. So (a) the vulnbox never needs a
# route back through us (it replies on-subnet), and (b) teams cannot attribute who attacked them,
# exactly like a real NAT'd A/D network.
for net in 10.60.1.0/24 10.60.2.0/24 10.60.99.0/24; do
    iptables -t nat -A POSTROUTING -d "$net" -j MASQUERADE
done

# --- NO NAT toward the infrastructure network ---------------------------------------------------
# Player -> submission keeps its real 10.66.N.x source address, so the submission server can map the
# connection to the right team (CTF_TEAMREGEX). (Nothing to do here: we simply don't masquerade the
# 10.60.0.0/24 infra net above.)

# --- Firewall: teams/players must never reach the gameserver database ----------------------------
iptables -A FORWARD -s 10.66.0.0/16 -d "${GS_POSTGRES_IP:-10.60.0.5}" -j DROP

echo "[gateway] ready. Interfaces:"
ip -brief addr show | sed 's/^/[gateway]   /'
echo "[gateway] WireGuard peers:"
wg show || true

# Print handshakes periodically so `docker compose logs gateway` shows player connections.
while true; do
    sleep 30
    wg show wg0 latest-handshakes 2>/dev/null | sed 's/^/[gateway][wg] /' || true
done
